    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    names = sorted(packages)
    best_vector = None
    best_assignment = None

    def solve_search(assignment):
        nonlocal best_vector, best_assignment

        bounds = {name: [interval[0], interval[1]] for name, interval in roots.items()}
        active = set(roots)

        # Each assigned row activates and constrains its dependencies.
        for name, row in assignment.items():
            if name not in active:
                return
            for dep in row.get('deps', []):
                dep_name = dep['name']
                active.add(dep_name)
                if dep_name not in bounds:
                    bounds[dep_name] = [dep['min'], dep['max']]
                else:
                    bounds[dep_name][0] = max(bounds[dep_name][0], dep['min'])
                    bounds[dep_name][1] = min(bounds[dep_name][1], dep['max'])

        for name, interval in bounds.items():
            if interval[0] > interval[1]:
                return
            if name not in packages:
                return
            if name in assignment:
                version = assignment[name]['version']
                if not interval[0] <= version <= interval[1]:
                    return

        domains = {}
        for name in active:
            if name in assignment:
                continue
            low, high = bounds[name]
            forbidden = blocked.get(name, [])
            domain = [row for row in packages[name]
                      if low <= row['version'] <= high
                      and row['version'] not in forbidden]
            if not domain:
                return
            domain.sort(key=lambda row: row['version'], reverse=True)
            domains[name] = domain

        # A safe lexicographic upper bound allows pruning after a solution exists.
        upper = []
        for name in names:
            if name in assignment:
                upper.append(assignment[name]['version'])
            elif name in domains:
                upper.append(max(row['version'] for row in domains[name]))
            else:
                versions = [row['version'] for row in packages[name]]
                upper.append(max([-1] + versions))
        upper = tuple(upper)
        if best_vector is not None and upper <= best_vector:
            return

        if not domains:
            vector = tuple(assignment[name]['version'] if name in assignment else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_assignment = dict(assignment)
            return

        name = min(domains)
        for row in domains[name]:
            next_assignment = dict(assignment)
            next_assignment[name] = row
            solve_search(next_assignment)

    solve_search({})
    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {'versions': {name: row['version']
                         for name, row in best_assignment.items()}}
